import json, os
base='/tmp/generate_payoff_Ig_source_s2'
gens=['gen_initial','gen_3','gen_4','gen_5']
data={}
for gen in gens:
 p=f'{base}/{gen}/arc_eval/predictions.json'
 data[gen]={r['task_id']:r for r in json.load(open(p)) if r.get('task_id')}
 print('\n'+gen)
 for tid,r in data[gen].items():
  if not r.get('solved',False):
   wrong=r.get('wrong_answers',[])
   dims=[]
   for g in wrong:
    if isinstance(g,list) and g and isinstance(g[0],list): dims.append((len(g),len(g[0])))
   print(tid, 'answers=',r.get('n_answers_returned'), 'wrong grids=',len(wrong),'dims=',dims[:2], 'error=',r.get('agent_error'))
print('\nTransitions:')
for a,b in zip(gens,gens[1:]):
 gained=[]; lost=[]
 for tid in data[a]:
  x=data[a][tid].get('solved',False); y=data[b][tid].get('solved',False)
  if y and not x:gained.append(tid)
  if x and not y:lost.append(tid)
 print(a,'->',b,'gained',gained,'lost',lost)
